  const nodu = findPlace("추포해수욕장 및 노둣길");
  nodu.basic = "추포 노둣길은 주민들이 갯벌 위에 돌을 놓고 쌓아 만든 전통 교통로로, 간조 때 드러나고 만조 때 잠긴다. 자연적으로 나타나는 얕은 바닥이 아니라 조석 환경에 적응해 사람이 조성한 문화경관이다. 이곳에서는 돌의 배열과 노면, 물때에 맞춘 이동 방식, 다리 개통 뒤 달라진 교통 생활을 함께 살펴본다.";
  nodu.deep = "노둣길은 자연 조건과 주민의 기술이 결합한 교통 유산이다. 조차가 큰 갯벌에 돌을 촘촘히 놓아 보행로를 만들었기 때문에 이용 시간은 조석 주기에 제한되었다. 오늘날에는 연도교와 도로가 이동의 중심이 되었지만, 노둣길은 물때가 생활 리듬과 생활권을 어떻게 조직했는지 보여 준다. 자연적으로 모래가 쌓인 육계사주와는 형성과정이 다르므로 구분해야 한다.";
  nodu.terms = "가) 노둣길\n갯벌을 건너기 위해 주민들이 돌을 놓고 쌓아 만든 전통 교통로. 간조 때 드러나고 만조 때 잠긴다.\n나) 조차\n만조와 간조 때 해수면 높이의 차이.\n다) 문화경관\n자연환경에 적응하며 이어 온 주민의 생활 방식과 기술이 공간에 남긴 경관.";

